 let trackedChanged=true;while(trackedChanged){trackedChanged=false;for(const i of live.items)if(i.type==='project'&&trackedPlanIds.has(i.parent)&&!trackedPlanIds.has(i.entityId)){trackedPlanIds.add(i.entityId);trackedChanged=true}}
 const project=live.items.find(i=>i.type==='project'&&i.entityId===projectId&&(i.workspace===workspaceId||trackedPlanIds.has(i.entityId)))

 useEffect(()=>{
  if(!workspace || !live.approved)return
  const paste=(event:ClipboardEvent)=>{
   const target=event.target as HTMLElement|null
   if(target?.closest('input,textarea,[contenteditable="true"],[role="dialog"]'))return
   const text=event.clipboardData?.getData('text/plain')||''
   if(!clipboardTasks(text).length)return
   event.preventDefault();setPasteText(text)
  }
  document.addEventListener('paste',paste)
  return()=>document.removeEventListener('paste',paste)
 },[workspace?.id,live.approved])
 const item=live.items.find(i=>i.id===selectedId&&(!workspaceId||i.workspace===workspaceId))
 const navigationMemory=useRef<{uid:string;items:Map<string,Item>}>({uid:'',items:new Map()})
 useEffect(()=>{
  const uid=live.user?.uid||''
  if(navigationMemory.current.uid!==uid)navigationMemory.current={uid,items:new Map()}
  // Never interpret an unfinished or failed subscription as a deletion.
  if(live.loading||!live.approved||Object.keys(live.errors).some(key=>key==='member'||key==='workspaces'||key.includes(':')))return
  const known=navigationMemory.current.items
  const recovered=recoverMissingRoute(locationState,live.items,live.workspaces.map(w=>w.id),known)
  if(editorItem&&known.has(editorItem.id)&&!live.items.some(i=>i.id===editorItem.id))setEditorItem(null)
  if(recovered){
   history.replaceState(null,'',`${location.pathname}?${recovered}`)
   setLocationState(recovered);setDetailsOpen(false);setInboxNotice(null)
   setCreation(null);setSelection(new Set());setPanel('details')
   setSearch('');setFilter('all');setStatusFilter('');setContentView(null)
  }
  rememberNavigationItems(live.items,known)
 },[live.user?.uid,live.loading,live.approved,live.errors,live.items,live.workspaces,locationState,editorItem])

 const conversationWorkspace=item?live.workspaces.find(w=>w.id===item.workspace):workspace

 const conversation=useLiveConversation(conversationWorkspace,chat?undefined:item,live.user?.uid||'',live.privileged,live.approved&&!chat&&!!item&&detailsOpen,live.items,commentLimit)

 const panelRef=useRef<HTMLElement>(null)
 useEffect(()=>{const target=panelRef.current;if(!target||chat||!detailsOpen)return;let timer:ReturnType<typeof setTimeout>;const observer=new ResizeObserver(()=>{clearTimeout(timer);timer=setTimeout(()=>{const rect=target.getBoundingClientRect();try{localStorage.setItem('workhub-details-panel-size',JSON.stringify({width:rect.width,height:rect.height}))}catch{}},200)});observer.observe(target);return()=>{observer.disconnect();clearTimeout(timer)}},[detailsOpen,chat])
 useEffect(()=>{const outside=(e:PointerEvent)=>{if(!(e.target as HTMLElement).closest('.creation-popover,.tree-add'))setCreation(null)};const exclusive=()=>setCreation(null);document.addEventListener('pointerdown',outside);document.addEventListener('workhub-dropdown-open',exclusive);return()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('workhub-dropdown-open',exclusive)}},[])
 const closeRef=useRef<HTMLButtonElement>(null)

 const lastTrigger=useRef<HTMLElement|null>(null)

 const t=(key:string)=>(language==='ar'?ar:en)[key as Key]||key

 const numberFormat=useMemo(()=>new Intl.NumberFormat(t('dateLocale')),[language])

 const dateFormat=useMemo(()=>new Intl.DateTimeFormat(t('dateLocale'),{day:'numeric',month:'short',timeZone:'Asia/Muscat'}),[language])

 const count=(value:number)=>numberFormat.format(value)

 const date=(value:string)=>{if(!value)return '—';const parsed=new Date(/^\d{4}-\d{2}-\d{2}$/.test(value)?value+'T12:00:00':value);return Number.isNaN(parsed.getTime())?value:dateFormat.format(parsed)}

 const displayName=live.member?.displayName||live.user?.displayName||live.user?.email||t('member')

 const initials=(value:string)=>value.trim().split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase()||'•'

 const owner=(uid:string)=>uid===live.user?.uid?displayName:live.people.find(person=>person.uid===uid)?.displayName||t('member')

 const navigate=(view:string,ws='',proj='',itemKey='')=>{if(!itemKey&&view==='workspaces'&&proj&&ws===workspaceId&&(selectedId||chat)){itemKey=proj?"project:"+proj:selectedId}const params=new URLSearchParams();params.set('view',view);if(view==='myWork'&&page==='myWork'&&locationState.get('workFilter'))params.set('workFilter',locationState.get('workFilter')!);if(ws)params.set('workspace',ws);if(proj)params.set('project',proj);if(itemKey)params.set('item',itemKey);history.pushState(null,'',`${location.pathname}?${params}`);setLocationState(params);setChat(false);if(view==='workspaces'&&ws&&!proj&&!itemKey)setDetailsOpen(false);if(!itemKey){setSearch('');setFilter('all')}setPanel('details');setStatusFilter('')}

 const close=()=>{setInboxNotice(null);if(!chat&&panelRef.current){const r=panelRef.current.getBoundingClientRect();setPanelSize({width:r.width,height:r.height})}setDetailsOpen(false);setChat(false);if(selectedId){const params=new URLSearchParams(locationState);params.delete('item');history.replaceState(null,'',`${location.pathname}?${params}`);setLocationState(params)}lastTrigger.current?.focus()}

 useEffect(()=>{const handle=()=>{setLocationState(new URLSearchParams(location.search));setChat(false);setSearch('');setFilter('all')};addEventListener('popstate',handle);return()=>removeEventListener('popstate',handle)},[])

 useEffect(()=>{document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';try{localStorage.setItem('workhub-prototype-language',language)}catch{}},[language])

 useEffect(()=>{document.documentElement.dataset.theme=theme;try{localStorage.setItem('workhub-prototype-theme',theme)}catch{}},[theme])

 useEffect(()=>{

  if((!item||!detailsOpen)&&!chat)return

  lastTrigger.current=document.activeElement as HTMLElement;closeRef.current?.focus()

  const handler=(event:KeyboardEvent)=>{

   if(event.key==='Escape')close()

  };document.addEventListener('keydown',handler);return()=>document.removeEventListener('keydown',handler)

 },[item?.id,chat,detailsOpen])

 useEffect(()=>{setDrafts({});setTaskDrafts({});setSelection(new Set());setStatusFilter('');setWriteError('');setExpandedCompleted(new Set(selectedId?[live.items.find(i=>i.id===selectedId)?.statusId||'']:[]))},[workspaceId,projectId])
 useEffect(()=>{if(!selectedId)return;const frame=requestAnimationFrame(()=>{const row=Array.from(document.querySelectorAll<HTMLElement>('[data-item-id]')).find(el=>el.dataset.itemId===selectedId);row?.scrollIntoView({block:'nearest',inline:'nearest'})});return()=>cancelAnimationFrame(frame)},[selectedId,projectId,live.items,expandedCompleted])
 const openWorkspace=(id:string)=>navigate('workspaces',id)

 const openItem=(next:Item,edit=false)=>{setInboxNotice(null);setEditingTaskTitle(false);setDetailsOpen(true);if(page==='inbox'){navigate('inbox','','',next.id);return}if(next.type==='project')navigate('workspaces',next.workspace,next.entityId,next.id);else navigate(page,page==='myWork'?'':next.workspace,projectId,next.id)}

 const goToItem=(target:Item)=>{const folder=target.type==='project'?target.entityId:target.parent;setContentView({context:target.workspace+':'+folder,mode:'list',range:'own'});setDetailsOpen(false);setFilter('all');setSearch('');setCollapsedGroups(new Set());setExpandedCompleted(new Set([target.statusId||'']));navigate('workspaces',target.workspace,folder,target.id)}
 const workspaceName=(id:string)=>live.workspaces.find(w=>w.id===id)?.name||'—'

 const scopeItems=live.items.filter(i=>page==='myWork'?i.type==='task'&&i.assigned.includes(live.user?.uid||''):workspace?i.workspace===workspace.id||(isPlansWorkspace(workspace)&&(trackedPlanIds.has(i.entityId)||trackedPlanIds.has(i.parent))):false).map(i=>workspace&&isPlansWorkspace(workspace)&&i.projectData?.planSettings?.sourceWorkspaceId===workspace.id?{...i,parent:i.projectData.planSettings.sourceParentProjectId||''}:i)

 const dashboardItems=project?scopeItems.filter(i=>{let parent=i.parent;const seen=new Set<string>();while(parent&&!seen.has(parent)){if(parent===project.entityId)return true;seen.add(parent);parent=scopeItems.find(p=>p.type==='project'&&p.entityId===parent)?.parent||''}return false}):scopeItems
 const selectedSubfolder=subfolderFilter?.context===contextKey?scopeItems.find(i=>i.type==='project'&&i.entityId===subfolderFilter.id):undefined
 const topLevelFolder=!!project&&!project.parent
 const topLevelLanding=topLevelFolder&&(!selectedSubfolder||contentView?.context===contextKey&&contentView.mode==='dashboard')
 const showDashboard=!!workspace&&(topLevelLanding||(contentView?.context===contextKey?contentView.mode==='dashboard':(!selectedId&&(!projectId||!dashboardItems.length))))
 useEffect(()=>{if(project?.taskItemDisplayMode==='list'||project?.taskItemDisplayMode==='cards')setLayout(project.taskItemDisplayMode)},[projectId,project?.taskItemDisplayMode])
 const showTasks=(range:'own'|'all'|'completed'|'overdue'|'sections')=>{setContentView({context:contextKey,mode:'list',range});setFilter(range==='sections'?'all':'task');setStatusFilter(range==='completed'?'__completed':range==='overdue'?'__overdue':'');setSearch('');if(range==='completed')setExpandedCompleted(new Set(['completed','done']))}
 const filteredFolder=!showDashboard&&subfolderFilter?.context===contextKey?scopeItems.find(i=>i.type==='project'&&i.entityId===subfolderFilter.id):undefined
 const contentProject=filteredFolder||project
 const visible=(listRange==='own'?(contentProject?folderContent(scopeItems,contentProject.entityId):scopeItems):dashboardItems).filter(i=>{

  if(listRange==='sections')return i.type==='project'&&(!project? !i.parent||!scopeItems.some(p=>p.type==='project'&&p.entityId===i.parent):i.parent===project.entityId)
  if(workspace&&i.type==='project')return false
  if(statusFilter==='__overdue'&&(i.type!=='task'||['completed','done'].includes(i.statusId||'')||remainingDays(i.due)===null||remainingDays(i.due)!>=0))return false
  if(search.trim())return i.title.toLocaleLowerCase(language).includes(search.trim().toLocaleLowerCase(language))&&(filter==='all'||i.type===filter)

  if(page==='myWork')return filter==='all'||i.type===filter

  if(filter==='all')return true

  return i.type===filter

 })

 const childCount=(id:string)=>scopeItems.filter(i=>i.parent===id).length

 const crumbs:Item[]=[];let cursor=project;const seen=new Set<string>();while(cursor&&!seen.has(cursor.id)){seen.add(cursor.id);crumbs.unshift(cursor);cursor=live.items.find(i=>i.type==='project'&&i.entityId===cursor?.parent&&i.workspace===workspaceId)}

 const originalLink=(id?:string,target?:Item|null)=> <a className="secondary" target="_blank" rel="noopener noreferrer" href={originalPath(id,target)}>{t('openOriginal')}<ArrowUpRight size={16}/></a>

 const peopleFor=(target:Item|undefined)=>eligiblePeople(live.workspaces.find(w=>w.id===target?.workspace)||workspace,target,live.items,live.people)
 const draftFor=(id:string):TaskDraft=>taskDrafts[id]||{assignees:live.user?.uid?[live.user.uid]:[],due:'',priority:'medium'}
 const dueLabel=(i:Item)=>{if(i.statusId&&['completed','done'].includes(i.statusId))return '';const days=remainingDays(i.due);return days===null?'':days===0?t('dueToday'):count(Math.abs(days))+' '+t(days<0?'daysOverdue':'daysLeft')}
 const selectedTasks=scopeItems.filter(i=>i.type==='task'&&selection.has(i.id))
 const bulkStatuses=selectedTasks[0]?.statuses?.filter(status=>selectedTasks.every(i=>i.statuses?.some(s=>s.id===status.id)))||[]
 const bulkPeople=selectedTasks.length?peopleFor(selectedTasks[0]).filter(p=>selectedTasks.every(i=>peopleFor(i).some(person=>person.uid===p.uid))):[]
 const bulkSave=async(action:'status'|'assignee'|'delete',value='')=>{if(busy||!selectedTasks.length)return;if(action==='delete'&&!window.confirm(t('confirmDelete')))return;setBusy('bulk');setWriteError('');try{for(const target of selectedTasks){if(action==='delete')await deleteWorkhubTask(target.entityId);else await updateWorkhubTask(target.entityId,action==='status'?{status:value}:{assigneeUid:value,assigneeUids:value?[value]:[]});setSelection(previous=>{const next=new Set(previous);next.delete(target.id);return next})}}catch{setWriteError(t('saveFailed'))}finally{setBusy('')}}
 const conversationView=<div className="conversation">{conversation.loading&&<LoadingSkeleton label={t('loading')} rows={3}/>}{conversation.error&&<p className="error-note" role="alert">{t('loadError')} ({conversation.error})</p>}<div className="messages" key={item?.id}><div className="discussion-history">{conversation.entries.length>=commentLimit&&<button className="secondary" onClick={()=>setCommentLimit(commentLimit+100)}>{t('loadOlder')}</button>}{conversation.entries.map(entry=><div className="message" key={entry.id}><span className="avatar">{initials(owner(entry.author))}</span><div><strong>{owner(entry.author)}</strong>{entry.time>0&&<small> · {date(new Date(entry.time).toISOString())}</small>}{editingComment===entry.id?<form onSubmit={async e=>{e.preventDefault();try{await updateWorkhubComment(entry.id,{body:commentText});setEditingComment('')}catch{setAuthError(t('saveFailed'))}}}><textarea value={commentText} onChange={e=>setCommentText(e.target.value)}/><button className="secondary">{t('save')}</button><button type="button" className="secondary" onClick={()=>setEditingComment('')}>{t('cancel')}</button></form>:<p dir="auto">{entry.body}</p>}{item&&<div className="message-reactions">{['👍','❤️','✅'].map(emoji=><button key={emoji} aria-label={t(emoji==='👍'?'reactionLike':emoji==='❤️'?'reactionLove':'reactionDone')} aria-pressed={entry.reactions[live.user?.uid||'']===emoji} onClick={()=>{void setWorkhubCommentReaction({commentId:entry.id,userUid:live.user!.uid,reaction:entry.reactions[live.user!.uid]===emoji?null:emoji}).catch(()=>setAuthError(t('saveFailed')))}}>{emoji==='👍'?<ThumbsUp size={19}/>:emoji==='❤️'?<Heart size={19}/>:<Check size={19}/>} {Object.values(entry.reactions).filter(v=>v===emoji).length||''}</button>)}{entry.author===live.user?.uid&&<><button onClick={()=>{setEditingComment(entry.id);setCommentText(entry.body)}}>{t('edit')}</button><button onClick={()=>{if(confirm(t('delete')+'?'))void deleteWorkhubComment(entry.id).catch(()=>setAuthError(t('saveFailed')))}}>{t('delete')}</button></>}</div>}</div></div>)}{!conversation.loading&&!conversation.error&&!conversation.entries.length&&<p className="empty">{t('noMessages')}</p>}</div></div>{item&&!chat?<DiscussionComposer key={item.id} item={item} uid={live.user?.uid||''} people={peopleFor(item)} t={t}/>:conversationWorkspace?<TeamChatComposer workspace={conversationWorkspace} uid={live.user?.uid||''} t={t}/>:null}</div>

