 {statusNotice&&<div className="task-status-toast" role="status"><div><strong>{t('taskStatusUpdated')}: {statusNotice.status}</strong><p>{t('taskStatusFindHint')}</p><small>{live.workspaces.find(w=>w.id===statusNotice.item.workspace)?.name} / {live.items.find(i=>i.type==='project'&&i.entityId===statusNotice.item.parent)?.title}</small></div><button className="secondary" disabled={!!busy} onClick={async()=>{const notice=statusNotice;setBusy(notice.item.id);try{await updateWorkhubTask(notice.item.entityId,{status:notice.item.statusId||'backlog'});setStatusNotice(null)}catch{setWriteError(t('saveFailed'))}finally{setBusy('')}}}>{t('undoStatusChange')}</button><button className="icon-button quiet" aria-label={t('close')} onClick={()=>setStatusNotice(null)}><X size={18}/></button></div>}
 {dismissTask&&<HrDialog title={t('finishOrRemove')} busy={!!busy} onClose={()=>setDismissTask(null)} footer={<><button className="secondary" disabled={!!busy} onClick={()=>setDismissTask(null)}>{t('cancel')}</button><button className="secondary danger" disabled={!!busy} onClick={async()=>{setBusy(dismissTask.id);setWriteError('');try{await deleteWorkhubTask(dismissTask.entityId);setDismissTask(null)}catch{setWriteError(t('saveFailed'))}finally{setBusy('')}}}>{t('removeTask')}</button><button className="primary" disabled={!!busy} onClick={async()=>{setBusy(dismissTask.id);setWriteError('');try{const completed=dismissTask.statuses?.find(s=>['completed','complete','done','closed'].includes(s.id)||s.icon==='check');await updateWorkhubTask(dismissTask.entityId,{status:completed?.id||'completed'});setStatusNotice({item:dismissTask,status:completed?.label||t('dashboardCompleted')});setDismissTask(null)}catch{setWriteError(t('saveFailed'))}finally{setBusy('')}}}>{t('dashboardCompleted')}</button></>}><p dir="auto">{dismissTask.title||dismissTask.description}</p><p>{t('finishOrRemoveHint')}</p>{writeError&&<p role="alert">{writeError}</p>}</HrDialog>}
 {toolsOpen&&workspace&&<div className="notes-modal-backdrop"><section className="workspace-tools-dialog" role="dialog" aria-modal="true" aria-label={t('workspaceTools')}><header><h2>{t('workspaceTools')}</h2><button className="icon-button quiet" aria-label={t('close')} onClick={()=>setToolsOpen(false)}><X size={20}/></button></header><SpecializedWorkspace key={workspace.id+projectId} workspace={workspace} items={dashboardItems} allItems={scopeItems} unreadNotifications={live.notifications.filter(n=>!n.read&&n.workspaceId===workspace.id).length} pendingMembersCount={live.people.filter(p=>p.status==='pending').length} parent={project} onCreated={id=>navigate('workspaces',workspace.id,id)} t={t}/></section></div>}
 {workspacePicker&&collapsed&&<div className="workspace-quick-picker"><header><strong>{t('workspaces')}</strong><button className="icon-button quiet" aria-label={t('close')} onClick={()=>setWorkspacePicker(false)}><X size={18}/></button></header><button className="workspace-page-shortcut" onClick={()=>{setWorkspacePicker(false);navigate('workspaces')}}><LayoutGrid size={18}/>{t('viewWorkspaces')}</button><div className="workspace-picker-cards">{live.workspaces.filter(w=>live.privileged||resolveWorkhubWorkspaceTemplateIdForWorkspace(w)!=='hr').map((w,index)=><button className={'workspace-picker-card'+(w.id===workspaceId?' current':'')} key={w.id} onClick={()=>{setWorkspacePicker(false);openWorkspace(w.id)}}><span className={'workspace-picker-icon '+['violet','orange','green','blue'][index%4]}><Folder size={20}/></span><span dir="auto">{w.name}</span></button>)}</div></div>}
 {agentOpen&&live.approved&&<AgentPanel currentProjectId={projectId} currentWorkspaceId={workspaceId} items={[...live.items,...live.workspaces.map(w=>({id:'project:root:'+w.id,entityId:'root:'+w.id,workspace:w.id,parent:'',title:w.name,type:'project' as const,status:'',owner:'',due:'',description:'',attachments:[],assigned:[],statuses:w.taskStatuses?.length?w.taskStatuses:live.items.find(i=>i.workspace===w.id&&i.statuses?.length)?.statuses}))]} uid={live.user?.uid||''} locale={language} t={t} onClose={()=>setAgentOpen(false)}/>}
